// Image Shader
#define MAX_SITES 100
#define MAX_STEPS 100
#define MIN_DIST 0.002
#define MAX_DIST 50.0
#define EPSILON 0.002
#define CELL_TRANSPARENCY 0.05
#define CUBE_SIZE 1.0
#define MAX_SITES_PER_CELL 50

// Where we stored yaw & pitch
const int ANGLE_ROW = 126;

struct Site {
    vec3 pos;
    float weight;
};

Site get_sites(int idx) {
    Site tr;
    tr.pos    = texelFetch(iChannel0, ivec2(idx, 0), 0).rgb;
    tr.weight = texelFetch(iChannel0, ivec2(idx, 0), 0).a;
    return tr;
}

int get_grid_count(int idx) {
    return int(texelFetch(iChannel0, ivec2(0, idx + 1), 0).r);
}

int get_grid_sites(int idx, int jdx) {
    return int(texelFetch(iChannel0, ivec2(jdx + 1, idx + 1), 0).r);
}

void getCellInfo(vec3 p, out float minDist, out int cellId, out float secondMinDist)
{
    minDist       = MAX_DIST;
    secondMinDist = MAX_DIST;
    cellId        = -1;

    // Convert position to the [0..4] grid index
    ivec3 gp = clamp(ivec3((p / CUBE_SIZE + 1.0)*0.5*5.0), ivec3(0), ivec3(4));
    int centerIdx = gp.x + 5*(gp.y + 5*gp.z);

    // center cell
    int ccount = get_grid_count(centerIdx);
    for (int i = 0; i < ccount; i++)
    {
        int siteId = get_grid_sites(centerIdx, i);
        float d    = length(p - get_sites(siteId).pos);
        if (d < minDist) {
            secondMinDist = minDist;
            minDist       = d;
            cellId        = siteId;
        }
        else if (d < secondMinDist) {
            secondMinDist = d;
        }
    }

    // neighbors
    for (int dx=-1; dx<=1; dx++)
    for (int dy=-1; dy<=1; dy++)
    for (int dz=-1; dz<=1; dz++)
    {
        if (dx==0 && dy==0 && dz==0) continue;
        ivec3 cell = gp + ivec3(dx,dy,dz);
        if (any(lessThan(cell, ivec3(0))) || any(greaterThanEqual(cell, ivec3(5))))
            continue;

        int idx = cell.x + 5*(cell.y + 5*cell.z);
        int count = get_grid_count(idx);
        for (int i = 0; i < count; i++)
        {
            int siteId = get_grid_sites(idx, i);
            float d = length(p - get_sites(siteId).pos);
            if (d < minDist) {
                secondMinDist = minDist;
                minDist       = d;
                cellId        = siteId;
            }
            else if (d < secondMinDist) {
                secondMinDist = d;
            }
        }
    }
}

// We'll pass in the scaled bounding box corners
vec2 cubeIntersection(vec3 ro, vec3 rd, vec3 negBox, vec3 posBox)
{
    vec3 invRd = 1.0 / rd;
    vec3 t1    = (negBox - ro)*invRd;
    vec3 t2    = (posBox - ro)*invRd;
    vec3 tmin  = min(t1, t2);
    vec3 tmax  = max(t1, t2);
    float tNear= max(max(tmin.x, tmin.y), tmin.z);
    float tFar = min(min(tmax.x, tmax.y), tmax.z);
    return vec2(tNear, tFar);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // normalized coords
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;

    // read yaw & pitch from Buffer A
    vec4 angles = texelFetch(iChannel0, ivec2(0, ANGLE_ROW), 0);
    float yaw   = angles.r;
    float pitch = angles.g;

    // Camera orbit radius
    float zoom = 2.5;

    // ------------------------------------------------
    // Vibrating scale factor
    //  => 80% ± 10% around center
    // ------------------------------------------------
    float baseScale  = 0.8;    // nominal size
    float vibrate    = 0.005;    // ±10% 
    float speed      = 3.14;   // how fast it oscillates
    float scaleFactor = baseScale + vibrate * sin(iTime*speed);

    // camera position from yaw/pitch
    float cx = zoom * sin(yaw) * cos(pitch);
    float cy = zoom * sin(pitch);
    float cz = zoom * cos(yaw) * cos(pitch);
    vec3 ro  = vec3(cx, cy, cz);

    // standard lookAt
    vec3 target  = vec3(0.0);
    vec3 forward = normalize(target - ro);
    vec3 right   = normalize(cross(vec3(0,1,0), forward));
    vec3 up      = cross(forward, right);
    vec3 rd      = normalize(mat3(right, up, forward)*vec3(uv,1.0));

    // Original gradient background
    vec3 backgroundColor = mix(
        vec3(0.25),
        vec3(0.015),
        clamp(1.0 - (uv.y*0.5 + 0.5), 0.0, 1.0)
    );
    vec4 finalColor = vec4(backgroundColor, 1.0);

    // Scale bounding box: [-1,1] => [-1*scaleFactor, +1*scaleFactor]
    vec3 negBox = vec3(-1.0)*scaleFactor;
    vec3 posBox = vec3( 1.0)*scaleFactor;

    // Ray-cube intersection
    vec2 tSpan = cubeIntersection(ro, rd, negBox, posBox);
    if (tSpan.x < tSpan.y && tSpan.y>0.0)
    {
        float t = max(tSpan.x, 0.0);
        float tEnd = min(tSpan.y, t + 2.0);
        vec4 acc   = vec4(0.0);

        for (int i=0; i<MAX_STEPS && t < tEnd; i++)
        {
            if (acc.a>0.99) break;

            vec3 pos = ro + rd*t;

            float minDist, secondDist;
            int cellId;
            getCellInfo(pos, minDist, cellId, secondDist);

            float boundaryDist  = abs(secondDist - minDist);
            float stepSize      = max(boundaryDist*0.25, 0.01);

            // Face glow factor
            float faceFactor    = exp(-boundaryDist*3.0);

            // Edges
            float edgeThreshold = 0.01;
            float edgeSharpness = smoothstep(edgeThreshold, 0.0, boundaryDist);

            // Pinkish-red centroid
            float centerDist    = length(pos - get_sites(cellId).pos);
            float dotCore       = 0.01;
            float dotGlow       = 0.03;
            float coreInt       = smoothstep(dotCore, 0.0, centerDist)*5.0;
            float glowInt       = smoothstep(dotGlow, dotCore, centerDist)*2.0;
            vec3 centroidColor  = vec3(0.016,0.000,1.000)*(coreInt + glowInt);

            // Combine
            float alpha   = (1.0 - acc.a)*0.08;
            vec3 faceGlow = vec3(1.0)*faceFactor*0.15;
            vec3 edge     = vec3(0.0)*edgeSharpness*3.0;
            vec3 color    = mix(faceGlow, edge, edgeSharpness) + centroidColor*1.5;

            acc += vec4(color*alpha, alpha);
            t   += stepSize;
        }

        // Composite onto background
        if (acc.a>0.0)
        {
            finalColor = mix(finalColor, vec4(acc.rgb/acc.a, acc.a), acc.a);
        }
    }

    fragColor = finalColor;
}

// Buffer A
#define MAX_SITES 100
#define MAX_STEPS 100
#define MIN_DIST 0.002
#define MAX_DIST 50.0
#define EPSILON 0.002
#define CELL_TRANSPARENCY 0.05
#define AUTO_ROTATE_SPEED 0.1
#define CUBE_SIZE 1.0
#define MAX_SITES_PER_CELL 50

// We store 2 rotation angles (yaw, pitch) in row=126: x=0
const int ANGLE_ROW = 126;

const vec3 CUBE_SIZE_VEC     = vec3(CUBE_SIZE);
const vec3 NEG_CUBE_SIZE_VEC = vec3(-CUBE_SIZE);

struct Site {
    vec3 pos;
    float weight;
};

vec3 hash33(vec3 p3) {
    p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 19.19);
    return -1.0 + 2.0 * fract((p3.xxy + p3.yzz) * p3.zyx);
}

ivec3 calculateGridPos(vec3 pos) {
    return clamp(ivec3((pos / CUBE_SIZE + 1.0) * 0.5 * 5.0), 
                 ivec3(0), ivec3(4));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 ipx = ivec2(fragCoord);
    float timeScale = iTime * 0.4;

    // --------------------------------------------------
    // 1) STORE / RETRIEVE YAW & PITCH in row=126
    // --------------------------------------------------
    if (ipx.y == ANGLE_ROW && ipx.x == 0)
    {
        // old angles
        vec4 oldAngles = texelFetch(iChannel0, ivec2(0, ANGLE_ROW), 0);
        float oldYaw   = oldAngles.r;
        float oldPitch = oldAngles.g;

        float newYaw   = oldYaw;
        float newPitch = oldPitch;

        // If mouse is dragging, compute new angles
        if(iMouse.z > 0.0)
        {
            // Yaw: 0..2π from mouse.x
            newYaw = (iMouse.x / iResolution.x) * 6.28318; 
            // Pitch: -π/2..+π/2 from mouse.y
            newPitch = (iMouse.y / iResolution.y)*3.14159 - 1.5708;
        }

        fragColor = vec4(newYaw, newPitch, 0.0, 1.0);
        return;
    }

    // --------------------------------------------------
    // 2) UPDATE SITE POSITIONS (row=0, columns=0..99)
    // --------------------------------------------------
    if (ipx.y == 0 && ipx.x < MAX_SITES)
    {
        float fi = float(ipx.x);

        // base position
        vec3 basePos = hash33(vec3(fi * 0.0573, fi * 0.0731, fi * 0.0917));

        // slow circular motion
        vec3 movement = vec3(
            sin(timeScale + fi * 0.5) * cos(timeScale * 0.7),
            cos(timeScale * 0.9 + fi * 0.4) * sin(timeScale * 0.6),
            sin(timeScale * 0.8 + fi * 0.3) * cos(timeScale * 0.5)
        ) * 0.3;

        // faster jitter
        vec3 fastNoise   = hash33(vec3(timeScale * 2.0 + fi * 0.1));
        vec3 quickMotion = fastNoise * 0.15 * sin(timeScale * 3.0 + fi);

        // combine and clamp
        vec3 finalPos = basePos + movement + quickMotion;
        vec3 pos = clamp(finalPos, vec3(-0.9), vec3(0.9)) * CUBE_SIZE;

        fragColor = vec4(pos, 1.0);
        return;
    }

    // --------------------------------------------------
    // 3) FILL GRID INFO (rows=1..125)
    // --------------------------------------------------
    int grid_size = 125;
    if (ipx.y > 0 && ipx.y <= grid_size)
    {
        int grid_index    = ipx.y - 1; // 0..124
        int sites_per_row = MAX_SITES_PER_CELL + 1;

        // column=0: store how many sites in that cell
        if (ipx.x == 0)
        {
            ivec3 grid_cell_pos = ivec3(
                grid_index % 5,
                (grid_index / 5) % 5,
                grid_index / 25
            );

            int grid_count = 0;
            for (int i = 0; i < MAX_SITES; i++)
            {
                vec3 site_pos = texelFetch(iChannel0, ivec2(i,0), 0).xyz;
                ivec3 cell    = calculateGridPos(site_pos);
                if (cell == grid_cell_pos)
                {
                    grid_count++;
                }
            }
            fragColor = vec4(float(grid_count), 0.0, 0.0, 0.0);
        }
        // columns=[1..MAX_SITES_PER_CELL]: store site IDs in that cell
        else if (ipx.x < sites_per_row)
        {
            ivec3 grid_cell_pos = ivec3(
                grid_index % 5,
                (grid_index / 5) % 5,
                grid_index / 25
            );
            int grid_count        = 0;
            int output_site_index = -1;

            for (int i = 0; i < MAX_SITES; i++)
            {
                vec3 site_pos = texelFetch(iChannel0, ivec2(i,0), 0).xyz;
                ivec3 cell    = calculateGridPos(site_pos);
                if (cell == grid_cell_pos)
                {
                    if (grid_count == ipx.x - 1)
                    {
                        output_site_index = i;
                    }
                    grid_count++;
                }
            }
            fragColor = vec4(float(output_site_index) + 0.5, 0.0, 0.0, 0.0);
        }
        else
        {
            fragColor = vec4(0.0);
        }
        return;
    }

    // All else: pass through from previous frame
    fragColor = texelFetch(iChannel0, ipx, 0);
}
